    {
      "line": 550,
      "text": "\n"
    },
    {
      "line": 551,
      "text": "**Severity:** HIGH (CVSS 3.1: 7.5 - AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N)  \n"
