    {
      "line": 567,
      "text": "\n"
    },
    {
      "line": 568,
      "text": "# Create devices for other users (privilege escalation)\n"
    },
    {
      "line": 569,
      "text": "curl -X POST /api/devices -d '{\"name\":\"backdoor\",\"owner_id\":1}' -H \"Content-Type: application/json\"\n"
    },
    {
      "line": 570,
      "text": "```\n"
    },
    {
      "line": 571,
      "text": "\n"
    },
    {
      "line": 572,
      "text": "#### Impact\n"
    },
    {
      "line": 573,
      "text": "- User enumeration and PII disclosure\n"
    },
    {
      "line": 574,
      "text": "- Horizontal privilege escalation\n"
    },
    {
      "line": 575,
      "text": "- Unauthorized device provisioning\n"
    },
    {
      "line": 576,
      "text": "\n"
    },
    {
      "line": 577,
      "text": "#### Remediation\n"
    },
    {
      "line": 578,
      "text": "Implement proper authorization checks:\n"
    },
    {
      "line": 579,
      "text": "```python\n"
    },
    {
      "line": 580,
      "text": "def get_current_user_id():\n"
    },
    {
      "line": 581,
      "text": "    # Extract from validated JWT token\n"
    },
    {
      "line": 582,
      "text": "    token = request.headers.get('Authorization', '').replace('Bearer ', '')\n"
    },
    {
      "line": 583,
      "text": "    payload = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])\n"
    },
    {
      "line": 584,
      "text": "    return payload['user_id']\n"
    },
    {
      "line": 585,
      "text": "\n"
    },
    {
      "line": 586,
      "text": "@app.route('/api/profile/<int:user_id>')\n"
    },
    {
      "line": 587,
      "text": "def get_profile(user_id):\n"
    },
    {
      "line": 588,
      "text": "    current_user = get_current_user_id()\n"
    },
    {
      "line": 589,
      "text": "    # Users can only access their own profile unless admin\n"
    },
    {
      "line": 590,
      "text": "    if current_user != user_id and not is_admin(current_user):\n"
    },
    {
      "line": 591,
      "text": "        return jsonify({'error': 'Forbidden'}), 403\n"
    },
    {
      "line": 592,
      "text": "    # ... rest of logic\n"
    },
    {
      "line": 593,
      "text": "```\n"
    },
    {
